		assertNotNull(event.event_id);
	}
}

package com.wolklaw.osrstoolkit;

import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class OfferSnapshotTest
{
	@Test
	public void keepsTheSameLifecycleForMonotonicFillUpdates()
	{
		OfferSnapshot previous = OfferSnapshot.from(
			2,
			new TestOffer(100, 1_000, 10, 10_000, GrandExchangeOfferState.BUYING),
			"Test item"
		);
		OfferSnapshot current = OfferSnapshot.from(
			2,
			new TestOffer(100, 1_000, 15, 15_100, GrandExchangeOfferState.BUYING),
			"Test item"
		);

		assertTrue(current.continues(previous));
		assertEquals("buy", current.side());
		assertEquals(5, current.quantityFilled - previous.quantityFilled);
		assertEquals(5_100, current.spentGp - previous.spentGp);
	}

	@Test
	public void changedOfferPriceStartsANewLifecycle()
	{
		OfferSnapshot previous = OfferSnapshot.from(
			0,
			new TestOffer(100, 1_000, 0, 0, GrandExchangeOfferState.SELLING),
			"Test item"
		);
		OfferSnapshot replacement = OfferSnapshot.from(
			0,
			new TestOffer(100, 1_050, 0, 0, GrandExchangeOfferState.SELLING),
			"Test item"
		);

		assertFalse(replacement.continues(previous));
		assertEquals("sell", replacement.side());
	}

	@Test
	public void completedOfferCannotBecomeANewOfferInTheSameLifecycle()
	{
		OfferSnapshot completed = OfferSnapshot.from(
			1,
			new TestOffer(100, 1_000, 100, 100_000, GrandExchangeOfferState.BOUGHT),
			"Test item"
		);
		OfferSnapshot newOffer = OfferSnapshot.from(
			1,
			new TestOffer(100, 1_000, 100, 100_000, GrandExchangeOfferState.BUYING),
			"Test item"
		);

		assertFalse(newOffer.continues(completed));
	}

	@Test
	public void cancellingAnOfferIsBothTerminalAndCancelled()
	{
		OfferSnapshot cancelled = OfferSnapshot.from(
			4,
			new TestOffer(100, 1_000, 30, 30_000, GrandExchangeOfferState.CANCELLED_BUY),
			"Test item"
		);

		assertTrue(cancelled.isCancelled());
		assertTrue(cancelled.isTerminal());
		assertEquals("buy", cancelled.side());
	}

	@Test
	public void anOpenOfferIsNotTreatedAsCancelled()
	{
		OfferSnapshot buying = OfferSnapshot.from(
			4,
			new TestOffer(100, 1_000, 30, 30_000, GrandExchangeOfferState.BUYING),
			"Test item"
		);

		assertFalse(buying.isCancelled());
		assertFalse(buying.isTerminal());
	}

	@Test
	public void aStateThisBuildDoesNotRecogniseDegradesInsteadOfThrowing()
	{
		// What a damaged or future-schema state file on disk deserialises into.
		OfferSnapshot damaged = new OfferSnapshot();
		damaged.itemId = 100;
		damaged.totalQuantity = 10;
		damaged.state = "SOMETHING_NEW";

		assertFalse(damaged.isValid());
		assertEquals("", damaged.side());
		assertFalse(damaged.isTerminal());
		assertFalse(damaged.isCancelled());
		assertFalse(damaged.isEmpty());

		OfferSnapshot missingState = new OfferSnapshot();
		missingState.itemId = 100;
		missingState.totalQuantity = 10;

		assertFalse(missingState.isValid());
		assertFalse(missingState.isEmpty());
	}

	@Test
	public void aCollectedSlotReadsAsEmptySoAReconcileDropsIt()
	{
		// The positive case the two assertions above are the negatives of, and the one the
		// heartbeat reconcile leans on: after the player collects, the game reports the slot
		// as EMPTY, and it has to fall out of the map rather than be resent as a live offer.
		OfferSnapshot collected = new OfferSnapshot();
		collected.itemId = 100;
		collected.totalQuantity = 10;
		collected.state = "EMPTY";

		assertTrue(collected.isEmpty());

		OfferSnapshot neverUsed = new OfferSnapshot();
		neverUsed.itemId = 0;
		neverUsed.totalQuantity = 0;

		assertTrue(neverUsed.isEmpty());
	}

	@Test
	public void anUnusablePreviousSnapshotNeverContinuesALifecycle()
	{
		OfferSnapshot damaged = new OfferSnapshot();
		damaged.itemId = 100;
		damaged.offerPrice = 1_000;
		damaged.totalQuantity = 100;
		damaged.state = "SOMETHING_NEW";

		OfferSnapshot current = OfferSnapshot.from(
			0,
			new TestOffer(100, 1_000, 5, 5_000, GrandExchangeOfferState.BUYING),
			"Test item"
		);

		assertFalse(current.continues(damaged));
	}

	private static final class TestOffer implements GrandExchangeOffer
	{
		private final int itemId;
		private final int price;
		private final int quantitySold;
		private final int spent;
		private final GrandExchangeOfferState state;

		private TestOffer(int itemId, int price, int quantitySold, int spent,
			GrandExchangeOfferState state)
		{
			this.itemId = itemId;
			this.price = price;
			this.quantitySold = quantitySold;
			this.spent = spent;
			this.state = state;
		}

		@Override
		public int getQuantitySold()
		{
			return quantitySold;
		}

		@Override
		public int getItemId()
		{
			return itemId;
		}

		@Override
		public int getTotalQuantity()
		{
			return 100;
		}

		@Override
		public int getPrice()
		{
			return price;
		}

		@Override
		public int getSpent()
		{
			return spent;
		}

		@Override
		public GrandExchangeOfferState getState()
		{
			return state;
		}
	}
}

package com.wolklaw.osrstoolkit;

import java.io.IOException;
import javax.annotation.Nonnull;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okio.BufferedSink;
import okio.GzipSink;
import okio.Okio;

/**
 * Talks to the OSRS Toolkit sync service.
 *
 * Every call goes on OkHttp's thread pool, so nothing here holds up the client thread or the
 * one that owns the outbox. Results arrive on an OkHttp thread.
 */
@Slf4j
final class SyncClient
{
	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

	/**
	 * Compiled in rather than configurable: the server is open source, so anyone self-hosting
	 * is already building from source. As a settings field it mostly offered a way to break
	 * your own sync with a typo.
	 */
	static final String SERVICE_URL = "https://sync.runescope.app";

	/**
	 * Not politeness: the CDN in front of the service filters partly on this, and OkHttp's
	 * default name is shared with every other Java client on the internet. Being blocked for
	 * looking generic would break every install at once, behind a fix that needs Hub review.
	 */
	private static final String USER_AGENT = "OSRS-Toolkit-Sync/1.0 (+https://runescope.app)";

	/** What became of one request: whether the payload is worth sending again. */
	enum Outcome
	{
		/** Stored. Anything queued for this request can be dropped. */
		DELIVERED,
		/** Nothing arrived — offline, service down, timed out. Keep it and try later. */
		RETRY,
		/**
		 * The token is wrong or unknown. Keep the payload: the fault is in the settings, not in
		 * what was recorded, and someone fixing their token should not find the queue emptied
		 * behind them.
		 */
		UNAUTHORIZED,
		/** The service refused the payload itself and always will: malformed, or too large. */
		REFUSED
	}

	@FunctionalInterface
	interface Callback
	{
		void completed(Outcome outcome);
	}

	private final OkHttpClient httpClient;
	private volatile HttpUrl baseUrl;
	private volatile String token;

	SyncClient(OkHttpClient httpClient)
	{
		this.httpClient = httpClient;
	}

	/**
	 * Point at a service, or at nothing.
	 *
	 * Returns whether the plugin is configured enough to send anything at all — an address that
	 * is blank or not a URL, or a missing token, all mean the same thing to a caller: hold on to
	 * it, there is nowhere to put it yet.
	 */
	boolean configure(String url, String pairingToken)
	{
		HttpUrl parsed = url == null || url.trim().isEmpty() ? null : HttpUrl.parse(url.trim());
		this.baseUrl = parsed;
		this.token = pairingToken == null ? "" : pairingToken.trim();
		return isConfigured();
	}

	boolean isConfigured()
	{
		return baseUrl != null && !token.isEmpty();
	}

	/** Add to something the service is collecting: events, heartbeats. */
	void send(String path, String json, Callback callback)
	{
		dispatch("POST", path, json, callback);
	}

	/**
	 * Overwrite the one copy the service keeps: the slots, the open offer box.
	 *
	 * PUT rather than POST because the service routes on the verb and answers a POST to these
	 * paths with 405 - which {@link #outcomeOf} reads as a payload that will never be accepted,
	 * so it is dropped rather than retried. Live state then disappears in silence, while the
	 * heartbeat on the same client keeps reporting a healthy connection.
	 */
	void replace(String path, String json, Callback callback)
	{
		dispatch("PUT", path, json, callback);
	}

	private void dispatch(String method, String path, String json, Callback callback)
	{
		HttpUrl url = baseUrl;
		String pairingToken = token;
		if (url == null || pairingToken.isEmpty())
		{
			callback.completed(Outcome.RETRY);
			return;
		}
		Request request = new Request.Builder()
			.url(url.newBuilder().addPathSegments(path).build())
			.header("Authorization", "Bearer " + pairingToken)
			.header("User-Agent", USER_AGENT)
			.header("Content-Encoding", "gzip")
			.method(method, gzip(RequestBody.create(JSON, json)))
			.build();
		httpClient.newCall(request).enqueue(new okhttp3.Callback()
		{
			@Override
			public void onFailure(@Nonnull okhttp3.Call call, @Nonnull IOException ex)
			{
				// Nothing reached the service, so nothing has been recorded. Worth another go.
				log.debug("Unable to reach the sync service", ex);
				callback.completed(Outcome.RETRY);
			}

			@Override
			public void onResponse(@Nonnull okhttp3.Call call, @Nonnull Response response)
			{
				try (Response closed = response)
				{
					callback.completed(outcomeOf(closed.code()));
				}
			}
		});
	}

	/**
	 * What a status code means for the payload that produced it.
	 *
	 * A 4xx is usually the service saying this payload will never work — a body it will not
	 * parse, or one too large. Retrying those forever would wedge the queue behind something
	 * that can never leave it, so they are dropped.
	 *
	 * Two exceptions, both meaning "not this, not now" rather than "not ever". 429 is the
	 * service asking for a pause. 401 and 403 are the token being wrong, which is a settings
	 * problem: throwing away a queue because someone mistyped a token would lose real trades to
	 * fix a typo.
	 */
	private static Outcome outcomeOf(int code)
	{
		if (code >= 200 && code < 300)
		{
			return Outcome.DELIVERED;
		}
		if (code == 401 || code == 403)
		{
			log.debug("Sync service rejected the pairing token ({})", code);
			return Outcome.UNAUTHORIZED;
		}
		if (code == 429)
		{
			return Outcome.RETRY;
		}
		if (code >= 400 && code < 500)
		{
			log.debug("Sync service refused a request with {}", code);
			return Outcome.REFUSED;
		}
		return Outcome.RETRY;
	}

	/**
	 * Compress the body. Event payloads are mostly item names, which compress to roughly a fifth
	 * of their size — worth doing when the service may be someone's home connection.
	 */
	private static RequestBody gzip(RequestBody body)
	{
		return new RequestBody()
		{
			@Override
			public MediaType contentType()
			{
				return body.contentType();
			}

			@Override
			public long contentLength()
			{
				// Not known before compressing, and not worth a second pass to find out.
				return -1;
			}

			@Override
			public void writeTo(@Nonnull BufferedSink sink) throws IOException
			{
				try (BufferedSink gzipSink = Okio.buffer(new GzipSink(sink)))
				{
					body.writeTo(gzipSink);
				}
			}
		};
	}
}

package com.wolklaw.osrstoolkit;

import java.util.UUID;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;

final class OfferSnapshot
{
	int slot;
	int itemId;
	String itemName;
	int offerPrice;
	int totalQuantity;
	int quantityFilled;
	int spentGp;
	String state;
	String offerId;

	OfferSnapshot()
	{
	}

	static OfferSnapshot from(int slot, GrandExchangeOffer offer, String itemName)
	{
		OfferSnapshot snapshot = new OfferSnapshot();
		snapshot.slot = slot;
		snapshot.itemId = offer.getItemId();
		snapshot.itemName = itemName;
		snapshot.offerPrice = offer.getPrice();
		snapshot.totalQuantity = offer.getTotalQuantity();
		snapshot.quantityFilled = offer.getQuantitySold();
		snapshot.spentGp = offer.getSpent();
		snapshot.state = offer.getState().name();
		snapshot.offerId = UUID.randomUUID().toString();
		return snapshot;
	}

	/**
	 * Snapshots round-trip through JSON on disk, so a damaged or future-schema state file can
	 * hand back a state name this build does not know. Every reader goes through here so a bad
	 * value degrades into "unrecognised" instead of throwing and wedging Grand Exchange sync.
	 */
	GrandExchangeOfferState offerState()
	{
		if (state == null)
		{
			return null;
		}
		try
		{
			return GrandExchangeOfferState.valueOf(state);
		}
		catch (IllegalArgumentException ex)
		{
			return null;
		}
	}

	boolean isValid()
	{
		return offerState() != null;
	}

	boolean isEmpty()
	{
		return itemId <= 0 || totalQuantity <= 0 || offerState() == GrandExchangeOfferState.EMPTY;
	}

	String side()
	{
		GrandExchangeOfferState offerState = offerState();
		if (offerState == null)
		{
			return "";
		}
		switch (offerState)
		{
			case BUYING:
			case BOUGHT:
			case CANCELLED_BUY:
				return "buy";
			case SELLING:
			case SOLD:
			case CANCELLED_SELL:
				return "sell";
			default:
				return "";
		}
	}

	boolean continues(OfferSnapshot previous)
	{
		return previous != null
			&& previous.isValid()
			&& !previous.isTerminal()
			&& itemId == previous.itemId
			&& offerPrice == previous.offerPrice
			&& totalQuantity == previous.totalQuantity
			&& side().equals(previous.side())
			&& quantityFilled >= previous.quantityFilled
			&& spentGp >= previous.spentGp;
	}

	boolean isTerminal()
	{
		GrandExchangeOfferState offerState = offerState();
		return offerState == GrandExchangeOfferState.BOUGHT
			|| offerState == GrandExchangeOfferState.SOLD
			|| isCancelled();
	}

	boolean isCancelled()
	{
		GrandExchangeOfferState offerState = offerState();
		return offerState == GrandExchangeOfferState.CANCELLED_BUY
			|| offerState == GrandExchangeOfferState.CANCELLED_SELL;
	}
}

package com.wolklaw.osrstoolkit;

import java.util.Objects;

/**
 * Where in the Grand Exchange the player is standing.
 *
 * Unlike everything else this plugin reports, this has not happened yet — which is the point.
 * The numbers a trade needs sit on a row in the desktop app's journal, and the moment worth
 * pointing at that row is while the player is in front of the box waiting to be typed into.
 */
final class OfferScreen
{
	/** Zero where the interface is open but on nothing in particular. */
	final int itemId;
	final String itemName;
	/** "buy", "sell", or null where no item is chosen to have a side. */
	final String side;

	OfferScreen(int itemId, String itemName, String side)
	{
		this.itemId = itemId;
		this.itemName = itemName;
		this.side = side;
	}

	/** Compared every tick to decide whether anything is worth sending, so equality is the gate. */
	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof OfferScreen))
		{
			return false;
		}
		OfferScreen that = (OfferScreen) other;
		return itemId == that.itemId
			&& Objects.equals(itemName, that.itemName)
			&& Objects.equals(side, that.side);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(itemId, itemName, side);
	}
}

package com.wolklaw.osrstoolkit;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.event.ActionListener;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import javax.swing.JTextField;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;

/**
 * The pairing token and a live connection status, in the sidebar rather than the settings
 * panel it used to live in.
 *
 * RuneLite's settings panel draws each field once, when it is opened, and has no listener for
 * a value changing underneath it -- a plugin writing its own connection status there through
 * {@code ConfigManager} updates what is stored, but the open panel never repaints to show it.
 * This panel is the plugin's own component, so it updates the moment {@link #apply} is called,
 * logged in or not.
 */
final class OsrsToolkitSyncPanel extends PluginPanel
{
	private static final int WIDTH = PluginPanel.PANEL_WIDTH - 2 * PluginPanel.BORDER_OFFSET;

	private final JTextField tokenField = new JTextField();
	private final JTextArea statusLabel = wrappingText();

	OsrsToolkitSyncPanel(String initialToken, Consumer<String> onSubmit)
	{
		super(false);
		setLayout(new BorderLayout());
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		JPanel body = new JPanel();
		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		body.setBackground(ColorScheme.DARK_GRAY_COLOR);

		body.add(fullWidth(title()));
		body.add(Box.createVerticalStrut(6));
		body.add(fullWidth(help()));
		body.add(Box.createVerticalStrut(12));
		body.add(fullWidth(tokenField));
		body.add(Box.createVerticalStrut(6));

		JButton connect = connectButton();
		ActionListener submit = event -> {
			String token = tokenField.getText().trim();
			if (!token.isEmpty())
			{
				onSubmit.accept(token);
			}
		};
		tokenField.addActionListener(submit);
		connect.addActionListener(submit);
		body.add(fullWidth(connect));
		body.add(Box.createVerticalStrut(10));

		statusLabel.setFont(FontManager.getRunescapeSmallFont());
		body.add(fullWidth(statusLabel));

		tokenField.setText(initialToken);
		tokenField.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		tokenField.setForeground(Color.WHITE);
		tokenField.setFont(FontManager.getRunescapeSmallFont());
		setNeutral("Not sending. Switch on \"Send to OSRS Toolkit Sync\" in this plugin's settings.");

		add(body, BorderLayout.NORTH);
	}

	private static JLabel title()
	{
		JLabel title = new JLabel("OSRS Toolkit Sync");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		return title;
	}

	private static JTextArea help()
	{
		JTextArea help = wrappingText();
		help.setFont(FontManager.getRunescapeSmallFont());
		help.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		setWrappedText(help,
			"Paste the pairing token from your Profile page on runescope.app, then press "
				+ "Enter or Connect.");
		return help;
	}

	/**
	 * A JLabel styled to look like one, but a real JTextArea underneath.
	 *
	 * An HTML JLabel does not know how many lines it needs until it has been laid out at a
	 * real width, and by then BoxLayout has often already asked for its preferred size once
	 * -- the classic Swing trap where wrapped text renders as one line, cropped. JTextArea
	 * reflows against whatever width it is actually given, but only reliably reports that in
	 * its own preferred size once it already knows that width, which is the same chicken-and
	 * -egg problem one level down: see {@link #setWrappedText}.
	 */
	private static JTextArea wrappingText()
	{
		JTextArea text = new JTextArea();
		text.setLineWrap(true);
		text.setWrapStyleWord(true);
		text.setEditable(false);
		text.setFocusable(false);
		text.setOpaque(false);
		text.setBorder(null);
		return text;
	}

	/**
	 * Set a wrapping text area's content and lock in the preferred height that content needs
	 * at this panel's fixed width, computed right now rather than left for BoxLayout to ask
	 * for later.
	 *
	 * A freshly built or freshly retexted JTextArea has not been given a width by any layout
	 * pass yet, so its own {@code getPreferredSize()} answers as if the text were one
	 * unwrapped line -- which is what BoxLayout asks for the moment it first measures this
	 * container, before ever assigning real widths. {@code setSize} first, so the text area's
	 * view has something to wrap against when {@code getPreferredSize()} is asked immediately
	 * after; the answer is then pinned down explicitly rather than trusted to survive.
	 */
	private static void setWrappedText(JTextArea area, String text)
	{
		area.setText(text);
		area.setSize(WIDTH, Short.MAX_VALUE);
		area.setPreferredSize(new Dimension(WIDTH, area.getPreferredSize().height));
	}

	private static JButton connectButton()
	{
		// setOpaque/setBorderPainted/setContentAreaFilled together are what it takes to get a
		// flat, theme-colored button out of Swing's native look and feel rather than a
		// Windows-grey one sitting in the middle of a dark panel.
		JButton button = new JButton("Connect");
		button.setFont(FontManager.getRunescapeSmallFont());
		button.setForeground(Color.WHITE);
		button.setBackground(ColorScheme.DARK_GRAY_HOVER_COLOR);
		button.setFocusPainted(false);
		button.setBorderPainted(false);
		button.setOpaque(true);
		return button;
	}

	/** Stretched to the panel's own width and pinned there, so BoxLayout does not shrink it
	 *  back down to its content -- the failure mode that put the button in the corner. */
	private static <T extends JComponent> T fullWidth(T component)
	{
		component.setAlignmentX(JComponent.LEFT_ALIGNMENT);
		component.setMaximumSize(new Dimension(WIDTH, Integer.MAX_VALUE));
		return component;
	}

	/** Neutral wording with no accent -- nothing has been tried yet, or nothing is wrong. */
	void setNeutral(String text)
	{
		apply(text, ColorScheme.LIGHT_GRAY_COLOR, ColorScheme.MEDIUM_GRAY_COLOR);
	}

	/** Green: the token was accepted and this character is syncing. */
	void setConnected(String text)
	{
		apply(text, ColorScheme.PROGRESS_COMPLETE_COLOR, ColorScheme.PROGRESS_COMPLETE_COLOR);
	}

	/** Red: the token itself is the problem. */
	void setRejected(String text)
	{
		apply(text, ColorScheme.PROGRESS_ERROR_COLOR, ColorScheme.PROGRESS_ERROR_COLOR);
	}

	/** Amber: the service didn't answer, which is not the token's fault. */
	void setUnreachable(String text)
	{
		apply(text, ColorScheme.BRAND_ORANGE, ColorScheme.BRAND_ORANGE);
	}

	/** Blue: a request is in flight. */
	void setChecking(String text)
	{
		apply(text, ColorScheme.PROGRESS_INPROGRESS_COLOR, ColorScheme.MEDIUM_GRAY_COLOR);
	}

	/**
	 * Called from the IO thread's callbacks by way of clientThread, which is not the EDT --
	 * but also from this panel's own constructor, which runs on the EDT already, since
	 * plugins start on the Swing thread. Queueing unconditionally would still repaint
	 * correctly there, just one event-queue turn later than it needs to.
	 */
	private void apply(String text, Color textColor, Color fieldAccent)
	{
		Runnable update = () -> {
			setWrappedText(statusLabel, text);
			statusLabel.setForeground(textColor);
			statusLabel.revalidate();
			tokenField.setBorder(BorderFactory.createCompoundBorder(
				BorderFactory.createLineBorder(fieldAccent, 2),
				BorderFactory.createEmptyBorder(3, 5, 3, 5)
			));
		};
		if (SwingUtilities.isEventDispatchThread())
		{
			update.run();
		}
		else
		{
			SwingUtilities.invokeLater(update);
		}
	}

	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(PluginPanel.PANEL_WIDTH, super.getPreferredSize().height);
	}

	// -- test-only observability; no production code reads these -------------------------

	String statusText()
	{
		return statusLabel.getText();
	}

	Color statusColor()
	{
		return statusLabel.getForeground();
	}

	void typeAndSubmit(String token)
	{
		tokenField.setText(token);
		for (ActionListener listener : tokenField.getActionListeners())
		{
			listener.actionPerformed(null);
		}
	}
}

package com.wolklaw.osrstoolkit;

import java.util.LinkedHashMap;
import java.util.Map;
import net.runelite.api.Item;

final class PendingPlayerTrade
{
	String counterparty = "Unknown player";
	final Map<Integer, Integer> given = new LinkedHashMap<>();
	final Map<Integer, Integer> received = new LinkedHashMap<>();

	void update(boolean isGiven, Item[] items)
	{
		Map<Integer, Integer> destination = isGiven ? given : received;
		destination.clear();
		if (items == null)
		{
			return;
		}
		for (Item item : items)
		{
			if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
			{
				continue;
			}
			destination.merge(item.getId(), item.getQuantity(), Integer::sum);
		}
	}

	boolean isEmpty()
	{
		return given.isEmpty() && received.isEmpty();
	}
}

